<?php
declare(strict_types=1);
session_start();
const APP_ROOT = __DIR__.'/..';
const CONFIG_FILE = APP_ROOT.'/config/config.php';
function cfg(): array { static $c; if ($c !== null) return $c; $c = is_file(CONFIG_FILE) ? require CONFIG_FILE : []; return $c; }
function installed(): bool { return is_file(CONFIG_FILE) && is_file(APP_ROOT.'/storage/installed.lock'); }
function db(): PDO { static $pdo; if ($pdo) return $pdo; $c=cfg(); $pdo=new PDO($c['db']['dsn'],$c['db']['user']??null,$c['db']['pass']??null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); return $pdo; }
function e(?string $v): string { return htmlspecialchars($v ?? '',ENT_QUOTES,'UTF-8'); }
function url(string $p='/'): string { $base=rtrim(dirname($_SERVER['SCRIPT_NAME'] ?? ''),'/'); return ($base==='/'?'':$base).'/'.ltrim($p,'/'); }
function redirect(string $p): never { header('Location: '.url($p)); exit; }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function check_csrf(): void { if(!hash_equals($_SESSION['csrf']??'',$_POST['_csrf']??'')){ http_response_code(419); exit('Invalid request token.'); } }
function user(): ?array { static $u; if($u!==null) return $u; if(empty($_SESSION['uid'])) return null; $s=db()->prepare('SELECT * FROM users WHERE id=?'); $s->execute([$_SESSION['uid']]); return $u=$s->fetch()?:null; }
function require_login(): void { if(!user()) redirect('/login'); }
function require_admin(): void { if(!user() || user()['role']!=='admin') { http_response_code(403); exit('Forbidden'); } }
function login_user(int $id): void { session_regenerate_id(true); $_SESSION['uid']=$id; }
function logout_user(): void { $_SESSION=[]; if(ini_get('session.use_cookies')) { $p=session_get_cookie_params(); setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']); } session_destroy(); }
function flash(?string $set=null): ?string { if($set!==null){$_SESSION['flash']=$set;return null;} $x=$_SESSION['flash']??null; unset($_SESSION['flash']); return $x; }
function render(string $title,string $content): void { $site=cfg()['site']??['name'=>'GameScore','accent'=>'#8b5cf6']; $u=user(); $f=flash(); require APP_ROOT.'/views/layout.php'; }
function page_home(): void { $games=db()->query('SELECT * FROM games WHERE published=1 ORDER BY featured DESC,updated_at DESC LIMIT 6')->fetchAll(); $updates=db()->query('SELECT u.*,g.name game_name,g.slug FROM updates u JOIN games g ON g.id=u.game_id ORDER BY u.published_at DESC LIMIT 8')->fetchAll(); ob_start(); require APP_ROOT.'/views/home.php'; render('Discover games',ob_get_clean()); }
function page_games(): void { $games=db()->query('SELECT * FROM games WHERE published=1 ORDER BY name')->fetchAll(); ob_start(); require APP_ROOT.'/views/games.php'; render('Games',ob_get_clean()); }
function page_updates(): void { $updates=db()->query('SELECT u.*,g.name game_name,g.slug FROM updates u JOIN games g ON g.id=u.game_id ORDER BY u.published_at DESC LIMIT 50')->fetchAll(); ob_start(); require APP_ROOT.'/views/updates.php'; render('Latest updates',ob_get_clean()); }
function page_game(string $slug): void { $s=db()->prepare('SELECT * FROM games WHERE slug=? AND published=1');$s->execute([$slug]);$game=$s->fetch();if(!$game){http_response_code(404);exit('Game not found');}$s=db()->prepare('SELECT * FROM updates WHERE game_id=? ORDER BY published_at DESC LIMIT 30');$s->execute([$game['id']]);$updates=$s->fetchAll();ob_start();require APP_ROOT.'/views/game.php';render($game['name'],ob_get_clean()); }
function page_auth(bool $register): void { if(user()) redirect('/'); $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??''; if($register){$name=trim($_POST['name']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||strlen($name)<2)$error='Use a valid name, email and password of at least 8 characters.';else{try{$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);login_user((int)db()->lastInsertId());redirect('/dashboard');}catch(Throwable $x){$error='That email is already registered.';}}}else{$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){login_user((int)$u['id']);redirect('/dashboard');}$error='Email or password was incorrect.';}} ob_start();require APP_ROOT.'/views/auth.php';render($register?'Create account':'Sign in',ob_get_clean()); }
function page_dashboard(): void { $u=user(); ob_start();require APP_ROOT.'/views/dashboard.php';render('Dashboard',ob_get_clean()); }
function page_admin(): void { $games=db()->query('SELECT * FROM games ORDER BY name')->fetchAll();$sources=cfg()['sources']??[];$msg=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='game'){$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(trim($_POST['name'])));$s=db()->prepare('INSERT INTO games(name,slug,description,image_url,steam_appid,featured,published) VALUES(?,?,?,?,?,?,?)');$s->execute([trim($_POST['name']),$slug,trim($_POST['description']),trim($_POST['image_url']),($_POST['steam_appid']??'')?:null,!empty($_POST['featured']),1]);$msg='Game added.';}elseif($action==='update'){$s=db()->prepare('INSERT INTO updates(game_id,title,body,source_name,source_url,published_at,verified) VALUES(?,?,?,?,?,?,1)');$s->execute([(int)$_POST['game_id'],trim($_POST['title']),trim($_POST['body']),'Manual',url('/admin'),date('Y-m-d H:i:s')]);$msg='Update published.';}}ob_start();require APP_ROOT.'/views/admin.php';render('Admin',ob_get_clean()); }
function api_games(): never { header('Content-Type: application/json');echo json_encode(['data'=>db()->query('SELECT id,name,slug,description,image_url,updated_at FROM games WHERE published=1 ORDER BY name')->fetchAll()]);exit; }
function api_updates(): never { header('Content-Type: application/json');$q=db()->query('SELECT u.id,u.title,u.body,u.source_name,u.source_url,u.published_at,u.verified,g.name game FROM updates u JOIN games g ON g.id=u.game_id ORDER BY u.published_at DESC LIMIT 100');echo json_encode(['data'=>$q->fetchAll()]);exit; }
function api_cron(): never { $token=$_GET['token']??'';$cfg=cfg();if(!$token||!hash_equals($cfg['cron_token']??'',$token)){http_response_code(403);exit('Forbidden');}$count=sync_steam();header('Content-Type: application/json');echo json_encode(['imported'=>$count,'time'=>date(DATE_ATOM)]);exit; }
function sync_steam(): int { $count=0;foreach(db()->query('SELECT * FROM games WHERE steam_appid IS NOT NULL AND steam_appid<>0')->fetchAll() as $g){$u='https://api.steampowered.com/ISteamNews/GetNewsForApp/v2/?appid='.(int)$g['steam_appid'].'&count=10&maxlength=8000';$ctx=stream_context_create(['http'=>['timeout'=>8,'user_agent'=>'GameScore/1.0']]);$raw=@file_get_contents($u,false,$ctx);if(!$raw)continue;$json=json_decode($raw,true);foreach($json['appnews']['newsitems']??[] as $n){$s=db()->prepare('SELECT id FROM updates WHERE external_id=?');$s->execute(['steam:'.$n['gid']]);if($s->fetch())continue;$s=db()->prepare('INSERT INTO updates(game_id,title,body,source_name,source_url,external_id,published_at,verified) VALUES(?,?,?,?,?,?,?,1)');$s->execute([$g['id'],$n['title'],strip_tags($n['contents']??''),'Steam News',$n['url'],'steam:'.$n['gid'],date('Y-m-d H:i:s',(int)$n['date'])]);$count++;}}return $count; }
function stripe_checkout(): never { $p=cfg()['payments']??[];if(empty($p['enabled'])||empty($p['secret'])||empty($p['price_id'])){http_response_code(503);exit('Payments are not enabled. Configure Stripe first.');}$u=user();$post=['mode'=>'payment','success_url'=>url('/dashboard').'?payment=success','cancel_url'=>url('/dashboard').'?payment=cancelled','customer_email'=>$u['email'],'line_items[0][price]'=>$p['price_id'],'line_items[0][quantity]'=>'1'];$ch=curl_init('https://api.stripe.com/v1/checkout/sessions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($post),CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$p['secret']]]);$res=json_decode(curl_exec($ch)?:'{}',true);curl_close($ch);if(empty($res['url'])){http_response_code(502);exit('Stripe checkout could not be created.');}header('Location: '.$res['url']);exit; }
function stripe_webhook(): never { $p=cfg()['payments']??[];if(empty($p['enabled'])||empty($p['webhook_secret'])){http_response_code(404);exit;} $payload=file_get_contents('php://input')?:'';$sig=$_SERVER['HTTP_STRIPE_SIGNATURE']??'';$parts=[];foreach(explode(',',$sig) as $v){[$k,$val]=array_pad(explode('=',$v,2),2,'');$parts[$k]=$val;}if(empty($parts['t'])||empty($parts['v1'])){http_response_code(400);exit;} $expected=hash_hmac('sha256',$parts['t'].'.'.$payload,$p['webhook_secret']);if(!hash_equals($expected,$parts['v1'])){http_response_code(400);exit;}http_response_code(200);echo 'ok';exit; }
